import{_ as p,W as o,s as r,u as d,I as l,ah as t,Z as a,w as n,A as i}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const f=JSON.parse('{"title":"在 Linux 中怎样移除（删除）符号链接 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中怎样移除（删除）符号链接 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"在 Linux 中怎样移除（删除）符号链接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中怎样移除（删除）符号链接 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190921 How to Remove (Delete) Symbolic Links in Linux","title":"在 Linux 中怎样移除（删除）符号链接","tag":"201909"},"relativePath":"201909/20190921 How to Remove (Delete) Symbolic Links in Linux.md","filePath":"[post].md"}'),m={name:"201909/20190921 How to Remove (Delete) Symbolic Links in Linux.md"};function u(k,s,h,c,g,b){const e=o("Link");return d(),r("div",null,[l("p",null,[a(e,{href:"collector:",title:"lujun9972"},{default:i(()=>s[0]||(s[0]=[n("#")])),_:1}),s[5]||(s[5]=n(": subject: (How to Remove (Delete) Symbolic Links in Linux) ")),a(e,{href:"collector:",title:"lujun9972"},{default:i(()=>s[1]||(s[1]=[n("#")])),_:1}),s[6]||(s[6]=n(": via: (")),a(e,{href:"https://www.2daygeek.com/remove-delete-symbolic-link-softlink-linux/"},{default:i(()=>s[2]||(s[2]=[n("https://www.2daygeek.com/remove-delete-symbolic-link-softlink-linux/")])),_:1}),s[7]||(s[7]=n(") ")),a(e,{href:"collector:",title:"lujun9972"},{default:i(()=>s[3]||(s[3]=[n("#")])),_:1}),s[8]||(s[8]=n(": author: (Magesh Maruthamuthu ")),a(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>s[4]||(s[4]=[n("https://www.2daygeek.com/author/magesh/")])),_:1}),s[9]||(s[9]=n(")"))]),s[29]||(s[29]=t('<h1 id="在-linux-中怎样移除-删除-符号链接" tabindex="-1">在 Linux 中怎样移除（删除）符号链接 <a class="header-anchor" href="#在-linux-中怎样移除-删除-符号链接" aria-label="Permalink to 在 Linux 中怎样移除（删除）符号链接">​</a></h1><p>你可能有时需要在 Linux 上创建或者删除符号链接。如果有，你知道该怎样做吗？之前你做过吗？你踩坑没有？如果你踩过坑，那没什么问题。如果还没有，别担心，我们将在这里帮助你。</p><p>使用 <code>rm</code> 和 <code>unlink</code> 命令就能完成移除（删除）符号链接的操作。</p><h3 id="什么是符号链接" tabindex="-1">什么是符号链接？ <a class="header-anchor" href="#什么是符号链接" aria-label="Permalink to 什么是符号链接？">​</a></h3><p>符号链接（symlink）又称软链接，它是一种特殊的文件类型，在 Linux 中该文件指向另一个文件或者目录。它类似于 Windows 中的快捷方式。它能在相同或者不同的文件系统或分区中指向一个文件或着目录。</p><p>符号链接通常用来链接库文件。它也可用于链接日志文件和挂载的 NFS（网络文件系统）上的文件夹。</p><h3 id="什么是-rm-命令" tabindex="-1">什么是 rm 命令？ <a class="header-anchor" href="#什么是-rm-命令" aria-label="Permalink to 什么是 rm 命令？">​</a></h3>',7)),l("p",null,[a(e,{href:"https://www.2daygeek.com/linux-remove-files-directories-folders-rm-command/"},{default:i(()=>s[10]||(s[10]=[n("rm 命令")])),_:1}),s[11]||(s[11]=n(" 被用来移除文件和目录。它非常危险，你每次使用 ")),s[12]||(s[12]=l("code",null,"rm",-1)),s[13]||(s[13]=n(" 命令的时候要非常小心。"))]),s[30]||(s[30]=t(`<h3 id="什么是-unlink-命令" tabindex="-1">什么是 unlink 命令？ <a class="header-anchor" href="#什么是-unlink-命令" aria-label="Permalink to 什么是 unlink 命令？">​</a></h3><p><code>unlink</code> 命令被用来移除特殊的文件。它被作为 GNU Gorutils 的一部分安装了。</p><h3 id="_1-使用-rm-命令怎样移除符号链接文件" tabindex="-1">1) 使用 rm 命令怎样移除符号链接文件 <a class="header-anchor" href="#_1-使用-rm-命令怎样移除符号链接文件" aria-label="Permalink to 1) 使用 rm 命令怎样移除符号链接文件">​</a></h3><p><code>rm</code> 命令是在 Linux 中使用最频繁的命令，它允许我们像下列描述那样去移除符号链接。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm symlinkfile</span></span></code></pre></div><p>始终将 <code>rm</code> 命令与 <code>-i</code> 一起使用以了解正在执行的操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -i symlinkfile1</span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkfile1’? y</span></span></code></pre></div><p>它允许我们一次移除多个符号链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -i symlinkfile2 symlinkfile3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkfile2’? y</span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkfile3’? y</span></span></code></pre></div><h4 id="_1a-使用-rm-命令怎样移除符号链接目录" tabindex="-1">1a) 使用 rm 命令怎样移除符号链接目录 <a class="header-anchor" href="#_1a-使用-rm-命令怎样移除符号链接目录" aria-label="Permalink to 1a) 使用 rm 命令怎样移除符号链接目录">​</a></h4><p>这像移除符号链接文件那样。使用下列命令移除符号链接目录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -i symlinkdir</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkdir’? y</span></span></code></pre></div><p>使用下列命令移除多个符号链接目录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -i symlinkdir1 symlinkdir2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkdir1’? y</span></span>
<span class="line"><span>rm: remove symbolic link ‘symlinkdir2’? y</span></span></code></pre></div><p>如果你在结尾增加 <code>/</code>，这个符号链接目录将不会被删除。如果你加了，你将得到一个错误。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -i symlinkdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm: cannot remove ‘symlinkdir/’: Is a directory</span></span></code></pre></div><p>你可以增加 <code>-r</code> 去处理上述问题。<strong>但如果你增加这个参数，它将会删除目标目录下的内容，并且它不会删除这个符号链接文件。</strong>（LCTT 译注：这可能不是你的原意。）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rm -ri symlinkdir/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rm: descend into directory ‘symlinkdir/’? y</span></span>
<span class="line"><span>rm: remove regular file ‘symlinkdir/file4.txt’? y</span></span>
<span class="line"><span>rm: remove directory ‘symlinkdir/’? y</span></span>
<span class="line"><span>rm: cannot remove ‘symlinkdir/’: Not a directory</span></span></code></pre></div><h3 id="_2-使用-unlink-命令怎样移除符号链接" tabindex="-1">2) 使用 unlink 命令怎样移除符号链接 <a class="header-anchor" href="#_2-使用-unlink-命令怎样移除符号链接" aria-label="Permalink to 2) 使用 unlink 命令怎样移除符号链接">​</a></h3><p><code>unlink</code> 命令删除指定文件。它一次仅接受一个文件。</p><p>删除符号链接文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># unlink symlinkfile</span></span></code></pre></div><p>删除符号链接目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># unlink symlinkdir2</span></span></code></pre></div><p>如果你在结尾增加 <code>/</code>，你不能使用 <code>unlink</code> 命令删除符号链接目录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># unlink symlinkdir3/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>unlink: cannot unlink ‘symlinkdir3/’: Not a directory</span></span></code></pre></div><hr>`,27)),l("p",null,[s[15]||(s[15]=n("via: ")),a(e,{href:"https://www.2daygeek.com/remove-delete-symbolic-link-softlink-linux/"},{default:i(()=>s[14]||(s[14]=[n("https://www.2daygeek.com/remove-delete-symbolic-link-softlink-linux/")])),_:1})]),l("p",null,[s[20]||(s[20]=n("作者：")),a(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>s[16]||(s[16]=[n("Magesh Maruthamuthu")])),_:1}),s[21]||(s[21]=n(" 选题：")),a(e,{href:"https://github.com/lujun9972"},{default:i(()=>s[17]||(s[17]=[n("lujun9972")])),_:1}),s[22]||(s[22]=n(" 译者：")),a(e,{href:"https://github.com/arrowfeng"},{default:i(()=>s[18]||(s[18]=[n("arrowfeng")])),_:1}),s[23]||(s[23]=n(" 校对：")),a(e,{href:"https://github.com/wxy"},{default:i(()=>s[19]||(s[19]=[n("wxy")])),_:1})]),l("p",null,[s[26]||(s[26]=n("本文由 ")),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>s[24]||(s[24]=[n("LCTT")])),_:1}),s[27]||(s[27]=n(" 原创编译，")),a(e,{href:"https://linux.cn/"},{default:i(()=>s[25]||(s[25]=[n("Linux中国")])),_:1}),s[28]||(s[28]=n(" 荣誉推出"))])])}const x=p(m,[["render",u]]);export{f as __pageData,x as default};
